# Let me verify the interior detection for both demo and test

def flood_fill_interior(grid, shape_color, fill_color):
    """Find and mark interior cells (holes) in a shape"""
    rows = len(grid)
    cols = len(grid[0])

    # Mark reachable cells from edges as external ( остаются outside)
    visited = [[False]*cols for _ in range(rows)]
    queue = []

    # Add all edge cells that are background (0)
    for r in range(rows):
